/**
 * Seeded value-noise utilities. No external dependencies:
 * the PRNG, lattice hash, bilinear smoothing and fractal
 * summation (fBm) are all implemented inline.
 */

/** Deterministic 32-bit PRNG (mulberry32). Returns floats in [0, 1). */
export function mulberry32(seed: number): () => number {
  let a = seed >>> 0;
  return function (): number {
    a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

const LATTICE_SIZE = 256;
const LATTICE_MASK = 255;

/**
 * Classic 2D value noise: random values on an integer lattice,
 * bilinearly interpolated with a quintic fade for C2 smoothness.
 */
export class ValueNoise2D {
  private readonly perm: Uint8Array;

  constructor(seed: number) {
    const rand = mulberry32(seed);
    this.perm = new Uint8Array(LATTICE_SIZE);
    for (let i = 0; i < LATTICE_SIZE; i++) {
      this.perm[i] = Math.floor(rand() * 256) & LATTICE_MASK;
    }
  }

  /** Raw lattice value at integer coordinates (hashed via permutation). */
  private lattice(xi: number, yi: number): number {
    return this.perm[(this.perm[xi & LATTICE_MASK] + (yi & LATTICE_MASK)) & LATTICE_MASK] / 255;
  }

  /** Smooth noise value at arbitrary continuous coordinates, in [0, 1]. */
  sample(x: number, y: number): number {
    const x0 = Math.floor(x);
    const y0 = Math.floor(y);
    const fx = x - x0;
    const fy = y - y0;

    // Quintic fade (Perlin-style): smoother than plain smoothstep.
    const fade = (t: number): number => t * t * t * (t * (t * 6 - 15) + 10);
    const ux = fade(fx);
    const uy = fade(fy);

    const v00 = this.lattice(x0, y0);
    const v10 = this.lattice(x0 + 1, y0);
    const v01 = this.lattice(x0, y0 + 1);
    const v11 = this.lattice(x0 + 1, y0 + 1);

    const lerp = (a: number, b: number, t: number): number => a + (b - a) * t;
    return lerp(lerp(v00, v10, ux), lerp(v01, v11, ux), uy);
  }

  /**
   * Fractal Brownian motion: several octaves of value noise with
   * doubling frequency and halving amplitude, normalized to [0, 1].
   */
  fbm(x: number, y: number, octaves = 5, lacunarity = 2, gain = 0.5): number {
    let sum = 0;
    let amp = 1;
    let freq = 1;
    let norm = 0;
    for (let o = 0; o < octaves; o++) {
      sum += amp * this.sample(x * freq, y * freq);
      norm += amp;
      amp *= gain;
      freq *= lacunarity;
    }
    return sum / norm;
  }
}

