import { createHash } from "node:crypto";
import { ValueNoise2D } from "./noise.js";

export const MAP_SIZE = 64;
export const CELL_COUNT = MAP_SIZE * MAP_SIZE;

export type Biome = "SNOW" | "DESERT" | "GRASS" | "FOREST";

export interface WorldMap {
  seed: number;
  elevation: Float64Array; // normalized to [0, 1]
  moisture: Float64Array; // normalized to [0, 1]
  biomes: Biome[];
}

/** Generate 64x64 elevation and moisture fields from seeded fBm value noise. */
function generateFields(seed: number): { elevation: Float64Array; moisture: Float64Array } {
  const elevNoise = new ValueNoise2D(seed);
  const moistNoise = new ValueNoise2D(seed ^ 0x9e3779b9); // decorrelated streams

  const elevation = new Float64Array(CELL_COUNT);
  const moisture = new Float64Array(CELL_COUNT);

  // Base frequency: ~6 noise cells across the map, plus octaves for detail.
  const FREQ = 6 / MAP_SIZE;

  let eMin = Infinity;
  let eMax = -Infinity;
  let mMin = Infinity;
  let mMax = -Infinity;

  for (let y = 0; y < MAP_SIZE; y++) {
    for (let x = 0; x < MAP_SIZE; x++) {
      const i = y * MAP_SIZE + x;
      const nx = x * FREQ;
      const ny = y * FREQ;
      const e = elevNoise.fbm(nx, ny, 5);
      const m = moistNoise.fbm(nx, ny, 4);
      elevation[i] = e;
      moisture[i] = m;
      if (e < eMin) eMin = e;
      if (e > eMax) eMax = e;
      if (m < mMin) mMin = m;
      if (m > mMax) mMax = m;
    }
  }

  // Min-max normalize each field to [0, 1] so thresholds are meaningful.
  const normalize = (arr: Float64Array, min: number, max: number): void => {
    const span = max - min || 1;
    for (let i = 0; i < arr.length; i++) arr[i] = (arr[i] - min) / span;
  };
  normalize(elevation, eMin, eMax);
  normalize(moisture, mMin, mMax);

  return { elevation, moisture };
}

/**
 * Classification:
 *   elevation > 0.75            -> SNOW
 *   else moisture < 0.3         -> DESERT
 *   else moisture < 0.65        -> GRASS
 *   else                        -> FOREST
 */
function classify(elevation: Float64Array, moisture: Float64Array): Biome[] {
  const biomes: Biome[] = new Array<Biome>(CELL_COUNT);
  for (let i = 0; i < CELL_COUNT; i++) {
    if (elevation[i]! > 0.75) {
      biomes[i] = "SNOW";
    } else if (moisture[i]! < 0.3) {
      biomes[i] = "DESERT";
    } else if (moisture[i]! < 0.65) {
      biomes[i] = "GRASS";
    } else {
      biomes[i] = "FOREST";
    }
  }
  return biomes;
}

/**
 * Post-pass invariant: no DESERT cell may sit orthogonally adjacent to a
 * SNOW cell. Any violating DESERT becomes GRASS. Returns the raw map
 * (before the post-pass).
 */
export function generateRawMap(seed: number): WorldMap {
  const { elevation, moisture } = generateFields(seed);
  return { seed, elevation, moisture, biomes: classify(elevation, moisture) };
}

/**
 * Post-pass: force every DESERT orthogonally adjacent to a SNOW cell to
 * become GRASS. Returns the number of cells changed and the new grid.
 */
export function applySnowDesertRule(biomes: readonly Biome[]): { changed: number; result: Biome[] } {
  const result = biomes.slice();
  let changed = 0;
  for (let y = 0; y < MAP_SIZE; y++) {
    for (let x = 0; x < MAP_SIZE; x++) {
      const i = y * MAP_SIZE + x;
      if (result[i] !== "DESERT") continue;
      const neighbors = [
        x > 0 ? i - 1 : -1, // left
        x < MAP_SIZE - 1 ? i + 1 : -1, // right
        y > 0 ? i - MAP_SIZE : -1, // up
        y < MAP_SIZE - 1 ? i + MAP_SIZE : -1, // down
      ];
      if (neighbors.some((n) => n >= 0 && biomes[n] === "SNOW")) {
        result[i] = "GRASS";
        changed++;
      }
    }
  }
  return { changed, result };
}

/** Full pipeline: generation + post-pass. */
export function generateMap(seed: number): WorldMap & { postPassChanges: number } {
  const raw = generateRawMap(seed);
  const { changed, result } = applySnowDesertRule(raw.biomes);
  return { ...raw, biomes: result, postPassChanges: changed };
}

/** Count orthogonal DESERT–SNOW adjacencies in a biome grid. */
export function countDesertSnowAdjacencies(biomes: readonly Biome[]): number {
  let count = 0;
  for (let y = 0; y < MAP_SIZE; y++) {
    for (let x = 0; x < MAP_SIZE; x++) {
      const i = y * MAP_SIZE + x;
      if (biomes[i] !== "DESERT") continue;
      if (x < MAP_SIZE - 1 && biomes[i + 1] === "SNOW") count++;
      if (y < MAP_SIZE - 1 && biomes[i + MAP_SIZE] === "SNOW") count++;
    }
  }
  return count;
}

/** sha256 hex digest of the biome grid (row-major, newline-separated). */
export function hashBiomeGrid(biomes: readonly Biome[]): string {
  const h = createHash("sha256");
  for (let y = 0; y < MAP_SIZE; y++) {
    h.update(biomes.slice(y * MAP_SIZE, (y + 1) * MAP_SIZE).join(","));
    h.update("\n");
  }
  return h.digest("hex");
}

